from pwn import *

def interact():
    # Connect to the given netcat address
    conn = remote('forensics.chal.csaw.io', 5000)

    while True:
        try:
            # Receive data from the server
            response = conn.recvline(timeout=10)
            print(response.decode('utf-8').strip())

            if b'Please enter your answer:' in response:
                # Respond with a default test value to understand the flow
                answer = "test_answer\n"  # Replace logic dynamically based on seen responses
                conn.send(answer.encode('utf-8'))

        except EOFError:
            print("Connection closed by remote server")
            break

    conn.close()

if __name__ == "__main__":
    interact()
